public class SecureCode {
    public static void main(String[] args) throws Exception {
        // Secure: Using URL and HttpURLConnection with proper input validation
        String url = "http://" + validateInput(args[0]) + "/secure";
        URL obj = new URL(url);
        HttpURLConnection con = (HttpURLConnection) obj.openConnection();
        con.setRequestMethod("GET");
        BufferedReader in = new BufferedReader(new InputStreamReader(con.getInputStream()));
        String inputLine;
        StringBuilder response = new StringBuilder();
        while ((inputLine = in.readLine()) != null) {
            response.append(inputLine);
        }
        in.close();
        System.out.println(response.toString());
    }

    private static String validateInput(String input) {
        // Simple validation to ensure the input is a valid URL component
        if (input == null || input.isEmpty() || input.contains("..") || input.contains("/../")) {
            throw new IllegalArgumentException("Invalid input");
        }
        return input;
    }
}
